import { addMonths } from '/private/tmp/100-tricks-runs/d45c/without/m5-weekly-plans/r13/src/dates.js';

const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly' });
const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

export function nextCharge(sub, today) {
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

const gymPlan = { cycle: 'monthly', since: '2026-09-02' };
const musicPlan = { cycle: 'monthly', since: '2026-09-30' };

